export function Icon({ id, className }: { id: string; className?: string }) {
  const icon = icons[id];
  if (!icon) return null;
  return (
    <svg
      viewBox={icon.viewBox}
      preserveAspectRatio="xMidYMid meet"
      className={className}
      aria-hidden="true"
    >
      {icon.paths.map((p, i) => (
        <path
          key={i}
          d={p.d}
          fill={p.fill}
          stroke={p.stroke}
          strokeWidth={p.sw}
        />
      ))}
    </svg>
  );
}
